// Hand-written. Not generated by Speakeasy.
//
// A client's JWK Set is not a service's. A service's holds the keys Authlete
// signs and decrypts with, so it carries private material. A client's holds
// the keys Authlete verifies that client's signatures with and encrypts to, so
// it must be public, and Authlete enforces that by editing what it stores.
//
// Measured against the live API. Sending a client an RSA private key stores
// only the public half:
//
//	sent:   kty n e d p q dp dq qi kid alg use
//	stored: kty n e kid alg use
//
// and sending it a symmetric key stores nothing at all:
//
//	create response jwks: {"keys":[]}
//
// Neither is reported as an error, so the configuration and the server
// disagree for ever: every plan offers the same change, and applying it
// changes nothing. The private key also sits in Terraform state, for a key the
// server never kept.
//
// This type refuses both at plan time. Everything else it inherits from JWKS.
package customtypes

import (
	"context"
	"fmt"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/diag"
	"github.com/hashicorp/terraform-plugin-framework/types/basetypes"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// privateMembers are the string-valued JWK members that exist only in a
// private key. "d" covers RSA, EC and OKP alike; the rest are RSA's CRT
// parameters.
//
// RSA's seventh private member, "oth", is deliberately not here. It is an
// array of objects rather than a string, so the string check that reads this
// list cannot see it; ValidateDocument tests for it separately.
var privateMembers = []string{"d", "p", "q", "dp", "dq", "qi"}

// --- type -------------------------------------------------------------------

var _ basetypes.StringTypable = (*PublicJWKSType)(nil)

// PublicJWKSType is a JWK Set that may hold only public asymmetric keys.
type PublicJWKSType struct {
	basetypes.StringType
}

func (t PublicJWKSType) Equal(o attr.Type) bool {
	other, ok := o.(PublicJWKSType)
	if !ok {
		return false
	}
	return t.StringType.Equal(other.StringType)
}

func (t PublicJWKSType) String() string { return "customtypes.PublicJWKSType" }

func (t PublicJWKSType) ValueFromString(_ context.Context, in basetypes.StringValue) (basetypes.StringValuable, diag.Diagnostics) {
	return PublicJWKS{JWKS{StringValue: in}}, nil
}

func (t PublicJWKSType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	attrValue, err := t.StringType.ValueFromTerraform(ctx, in)
	if err != nil {
		return nil, err
	}

	stringValue, ok := attrValue.(basetypes.StringValue)
	if !ok {
		return nil, fmt.Errorf("unexpected value type %T, expected basetypes.StringValue", attrValue)
	}

	stringValuable, diags := t.ValueFromString(ctx, stringValue)
	if diags.HasError() {
		return nil, fmt.Errorf("unexpected error converting StringValue to StringValuable: %v", diags)
	}

	return stringValuable, nil
}

func (t PublicJWKSType) ValueType(_ context.Context) attr.Value { return PublicJWKS{} }

// --- value ------------------------------------------------------------------

var _ basetypes.StringValuableWithSemanticEquals = (*PublicJWKS)(nil)

// PublicJWKS is a JWK Set belonging to a client.
type PublicJWKS struct {
	JWKS
}

func (v PublicJWKS) Equal(o attr.Value) bool {
	other, ok := o.(PublicJWKS)
	if !ok {
		return false
	}
	return v.StringValue.Equal(other.StringValue)
}

func (v PublicJWKS) Type(_ context.Context) attr.Type { return PublicJWKSType{} }

// StringSemanticEquals delegates, after unwrapping the newer value to the
// shape the embedded type expects.
func (v PublicJWKS) StringSemanticEquals(ctx context.Context, newValuable basetypes.StringValuable) (bool, diag.Diagnostics) {
	newValue, ok := newValuable.(PublicJWKS)
	if !ok {
		var diags diag.Diagnostics
		diags.AddError(
			"Semantic Equality Check Error",
			fmt.Sprintf("expected value type %T but got %T. Please report this to the provider developers.", v, newValuable),
		)
		return false, diags
	}
	return v.JWKS.StringSemanticEquals(ctx, newValue.JWKS)
}

// NewPublicJWKSValue and friends mirror the constructors the framework expects.
func NewPublicJWKSValue(value string) PublicJWKS {
	return PublicJWKS{JWKS{StringValue: basetypes.NewStringValue(value)}}
}

func NewPublicJWKSNull() PublicJWKS {
	return PublicJWKS{JWKS{StringValue: basetypes.NewStringNull()}}
}

func NewPublicJWKSUnknown() PublicJWKS {
	return PublicJWKS{JWKS{StringValue: basetypes.NewStringUnknown()}}
}
